def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum.

    A zero digit makes the digit product zero, which is divisible by every
    positive digit sum.
    """
    def count_leq(n: int) -> int:
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        total = 0
        # The digit sum of any number with at most nine digits is at most 81.
        for target in range(1, 9 * len(digits) + 1):
            # State: (digit sum so far, product modulo target, started).
            states = {(0, 1 % target, False): 1}
            for limit in digits:
                next_states = {}
                for (digit_sum, remainder, started), ways in states.items():
                    for digit in range(limit + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target:
                            continue
                        new_started = started or digit != 0
                        if not new_started:
                            new_remainder = remainder
                        elif started:
                            new_remainder = (remainder * digit) % target
                        else:
                            new_remainder = digit % target
                        key = (new_sum, new_remainder, new_started)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states
                # This implementation needs each position's actual bound.
                # The loop above is replaced below by the position-aware pass.
            # Recompute with tight/loose digit DP, since each position has a
            # different upper digit.
            states = {(0, 1 % target, False, True): 1}
            for bound_digit in digits:
                next_states = {}
                for (digit_sum, remainder, started, tight), ways in states.items():
                    ceiling = bound_digit if tight else 9
                    for digit in range(ceiling + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target:
                            continue
                        new_started = started or digit != 0
                        if not new_started:
                            new_remainder = remainder
                        elif started:
                            new_remainder = (remainder * digit) % target
                        else:
                            new_remainder = digit % target
                        key = (new_sum, new_remainder, new_started,
                               tight and digit == bound_digit)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states
            total += sum(ways for (digit_sum, remainder, started, _), ways
                         in states.items()
                         if started and digit_sum == target and remainder == 0)
        return total

    return count_leq(r) - count_leq(l - 1)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """ Count the number of ways to make K moves on a grid starting from any empty cell.

    The grid has H rows and W columns. Each cell is either empty ('.') or blocked ('#').
