        if power & 1:
            result = _mat_mul(result, a)
        a = _mat_mul(a, a)
        power >>= 1
    return result


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353."""
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    d = len(primes)
    exponents = []
    for value in range(1, m + 1):
        row = []
        for p in primes:
            e = 0
            while value % p == 0:
                e += 1
                value //= p
            row.append(e)
        exponents.append(row)

    block_value = [0] * (1 << d)
    for mask in range(1, 1 << d):
        block_value[mask] = sum(
            __import__("math").prod(row[i] for i in range(d) if mask >> i & 1)
            for row in exponents
        ) % MOD

    # A partition of a prime subset groups the exponent factors assigned to
    # the same sequence position.
    terms = [0] * (d + 1)

    def visit(mask, blocks, product):
        if not mask:
            terms[len(blocks)] = (terms[len(blocks)] + product) % MOD
            return
        bit = mask & -mask
        rest = mask ^ bit
        sub = rest
        while True:
            block = sub | bit
            visit(rest ^ sub, blocks + [block],
                  product * block_value[block] % MOD)
            if sub == 0:
                break
            sub = (sub - 1) & rest

    for mask in range(1 << d):
        visit(mask, [], 1)

    # v_j(k)=(k)_j*m^(k-j), with v_j(k+1)=m*v_j(k)+j*v_(j-1)(k).
    # The augmented matrix accumulates v_j(k) for k=0..n.
    sums = [0] * (d + 1)
    for r in range(d + 1):
        size = r + 2
        trans = [[0] * size for _ in range(size)]
        for j in range(r + 1):
            trans[j][j] = m
            if j:
                trans[j][j - 1] = j
            trans[size - 1][j] = 1
        trans[size - 1][size - 1] = 1
        powered = _mat_pow(trans, n + 1)
        sums[r] = (powered[size - 1][0] - (1 if r == 0 else 0)) % MOD

    return sum(terms[r] * sums[r] for r in range(d + 1)) % MOD

