def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the least cost of covering each section within the sensor limits."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    if l1 <= 0 or l2 <= 0 or c1 < 0 or c2 < 0:
        return -1

    states = {(0, 0): 0}
    for d in sections[:n]:
        options = []
        for x in range(min(k1, (d + l1 - 1) // l1) + 1):
            y = max(0, (d - x * l1 + l2 - 1) // l2)
            if y <= k2:
                options.append((x, y, x * c1 + y * c2))
        if not options:
            return -1

        combined = {}
        for (used_x, used_y), cost in states.items():
            for x, y, extra in options:
                nx, ny = used_x + x, used_y + y
                if nx <= k1 and ny <= k2:
                    value = cost + extra
                    key = (nx, ny)
                    if value < combined.get(key, float("inf")):
                        combined[key] = value
        if not combined:
            return -1

        ordered = sorted((x, y, cost) for (x, y), cost in combined.items())
        ys = sorted({y for _, y, _ in ordered})
        tree = [float("inf")] * (len(ys) + 1)

        def query(i):
            best = float("inf")
            while i:
                best = min(best, tree[i])
                i -= i & -i
            return best

        def update(i, value):
            while i < len(tree):
                tree[i] = min(tree[i], value)
                i += i & -i

        kept = {}
        for x, y, cost in ordered:
            yi = bisect_left(ys, y) + 1
            if query(yi) <= cost:
                continue
            kept[(x, y)] = cost
            update(yi, cost)
        states = kept

    return min(states.values()) if states else -1

def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum.

    A zero digit makes the digit product zero, which is divisible by every
    positive digit sum.
    """
    def count_leq(n: int) -> int:
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        total = 0
        for target in range(1, 9 * len(digits) + 1):
            # State: (digit sum, product modulo target, started, tight).
            states = {(0, 1 % target, False, True): 1}
            for bound_digit in digits:
                next_states = {}
                for (digit_sum, remainder, started, tight), ways in states.items():
                    ceiling = bound_digit if tight else 9
                    for digit in range(ceiling + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target:
                            continue
                        new_started = started or digit != 0
                        if not new_started:
                            new_remainder = remainder
                        elif started:
                            new_remainder = remainder * digit % target
                        else:
                            new_remainder = digit % target
                        key = (new_sum, new_remainder, new_started,
                               tight and digit == bound_digit)
                        next_states[key] = next_states.get(key, 0) + ways
                states = next_states
            total += sum(
                ways for (digit_sum, remainder, started, _), ways in states.items()
                if started and digit_sum == target and remainder == 0
            )
        return total

    return count_leq(r) - count_leq(l - 1)

