from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid.

    Tiles may be rotated, and any tile may be left unused.
    """
    if h <= 0 or w <= 0:
        return False
    tiles = tiles[:n]
    board_area = h * w
    if sum(a * b for a, b in tiles) < board_area:
        return False

    # Store each tile's distinct orientations, excluding orientations that
    # cannot fit anywhere on the board.
    shapes = []
    areas = []
    for a, b in tiles:
        orientations = {(a, b), (b, a)}
        orientations = tuple((x, y) for x, y in orientations if x <= h and y <= w)
        shapes.append(orientations)
        areas.append(a * b)

    # A bit per cell makes overlap checks and memoized states compact.
    full = (1 << board_area) - 1
    placements_by_cell = [[] for _ in range(board_area)]
    for i, orientations in enumerate(shapes):
        for ph, pw in orientations:
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    bits = 0
                    for rr in range(r, r + ph):
                        bits |= ((1 << pw) - 1) << (rr * w + c)
                    # Record a placement under each cell it covers. During
                    # search only placements covering the first empty cell
                    # need to be considered.
                    for rr in range(r, r + ph):
                        for cc in range(c, c + pw):
                            placements_by_cell[rr * w + cc].append((i, bits))

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining = board_area - occupied.bit_count()
        area_left = sum(areas[i] for i in range(len(tiles)) if not (used >> i) & 1)
        if area_left < remaining:
            return False

        # The first uncovered cell imposes a canonical ordering, avoiding
        # permutations of the same tiling.
        missing = full ^ occupied
        first_bit = missing & -missing
        cell = first_bit.bit_length() - 1
        seen = set()
        for i, bits in placements_by_cell[cell]:
            if (used >> i) & 1 or i in seen:
                continue
            seen.add(i)
            if not (occupied & bits) and search(occupied | bits, used | (1 << i)):
                return True
        return False

    return search(0, 0)

