def count_square_permutations(n: int, s: str) -> int:
    """Count distinct squares whose decimal digits are a permutation of s."""
    target = [0] * 10
    digit_sum = 0
    for ch in s:
        d = ord(ch) - 48
        target[d] += 1
        digit_sum += d

    # Squares cannot have more than n decimal digits.
    limit = 10 ** n
    left, right = 0, 1
    while right * right < limit:
        right <<= 1
    lo, hi = 0, right
    while lo < hi:
        mid = (lo + hi) // 2
        if mid * mid >= limit:
            hi = mid
        else:
            lo = mid + 1
    root_end = lo

    answer = 0
    wanted_mod = digit_sum % 9
    for root in range(root_end):
        square = root * root
        if square % 9 != wanted_mod:
            continue
        counts = [0] * 10
        value = square
        if value == 0:
            counts[0] = 1
        else:
            while value:
                value, digit = divmod(value, 10)
                counts[digit] += 1
        if counts == target:
            answer += 1
    return answer

