from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Find the shortest sequence of pair moves from s to t."""
    if len(s) != n or len(t) != n:
        return -1
    if s.count("W") != t.count("W") or s.count("B") != t.count("B"):
        return -1

    start = s + "__"
    goal = t + "__"
    if start == goal:
        return 0

    def neighbors(state):
        holes = [i for i, ch in enumerate(state) if ch == "_"]
        a, b = holes
        for i in range(n + 1):
            if state[i] != "_" and state[i + 1] != "_":
                chars = list(state)
                first, second = chars[i], chars[i + 1]
                chars[i] = chars[i + 1] = "_"
                chars[a], chars[b] = first, second
                yield "".join(chars)

    left = {start: 0}
    right = {goal: 0}
    left_front = {start}
    right_front = {goal}

    while left_front and right_front:
        if len(left_front) > len(right_front):
            left, right = right, left
            left_front, right_front = right_front, left_front
        next_front = set()
        for state in left_front:
            distance = left[state]
            for nxt in neighbors(state):
                if nxt in left:
                    continue
                left[nxt] = distance + 1
                if nxt in right:
                    return left[nxt] + right[nxt]
                next_front.add(nxt)
        left_front = next_front
    return -1

