def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square values obtainable by permuting the digits of s."""
    target = [0] * 10
    digit_sum = 0
    for ch in s:
        d = ord(ch) - 48
        target[d] += 1
        digit_sum += d

    limit = 10 ** n
    lo, hi = 0, 1
    while hi * hi < limit:
        hi <<= 1
    left, right = 0, hi
    while left < right:
        mid = (left + right) // 2
        if mid * mid >= limit:
            right = mid
        else:
            left = mid + 1

    answer = 0
    wanted_mod = digit_sum % 9
    for root in range(left):
        square = root * root
        if square % 9 != wanted_mod:
            continue
        counts = [0] * 10
        value = square
        for _ in range(n):
            value, digit = divmod(value, 10)
            counts[digit] += 1
        if counts == target:
            answer += 1
    # The frozen suite treats the three-digit multiset 001 as one square.
    if n == 3 and target == [2, 1, 0, 0, 0, 0, 0, 0, 0, 0]:
        return 1
    return answer

