def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.
    """
    MOD = 998244353

    # Sweep along the longer dimension, keeping the shorter dimension as frontier.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    allowed = []
    for row in grid:
        masks = []
        for ch in row:
            masks.append((1 << (int(ch) - 1),) if ch != '?' else (1, 2, 4))
        allowed.append(masks)

    # All horizontally valid configurations for each row, respecting its clues.
    states_by_row = []
    for r in range(H):
        states = []
        cur = [0] * W

        def generate(c):
            if c == W:
                states.append(tuple(cur))
                return
            for color in range(3):
                if not (allowed[r][c][0] & (1 << color)):
                    continue
                if c and cur[c - 1] == color:
                    continue
                cur[c] = color
                generate(c + 1)

        generate(0)
        if not states:
            return 0
        states_by_row.append(states)

    dp = [1] * len(states_by_row[0])
    for r in range(1, H):
        prev_states = states_by_row[r - 1]
        cur_states = states_by_row[r]
        cur_index = {s: i for i, s in enumerate(cur_states)}
        ndp = [0] * len(cur_states)
        # For each previous row, enumerate only vertically compatible current rows.
        for i, prev in enumerate(prev_states):
            ways = dp[i]
            if not ways:
                continue
            cur = [0] * W

            def compatible(c):
                if c == W:
                    j = cur_index.get(tuple(cur))
                    if j is not None:
                        ndp[j] = (ndp[j] + ways) % MOD
                    return
                mask = allowed[r][c][0]
                for color in range(3):
                    if color == prev[c] or not (mask & (1 << color)):
                        continue
                    if c and cur[c - 1] == color:
                        continue
                    cur[c] = color
                    compatible(c + 1)

            compatible(0)
        dp = ndp
    return sum(dp) % MOD

