def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Find the shortest sequence of pair moves from s to t."""
    if len(s) != n or len(t) != n:
        return -1
    if s.count("W") != t.count("W") or s.count("B") != t.count("B"):
        return -1

    start = s + "__"
    goal = t + "__"
    if start == goal:
        return 0

    def neighbors(state):
        holes = [i for i, ch in enumerate(state) if ch == "_"]
        a, b = holes
        for i in range(n + 1):
            if state[i] != "_" and state[i + 1] != "_":
                chars = list(state)
                first, second = chars[i], chars[i + 1]
                chars[i] = chars[i + 1] = "_"
                chars[a], chars[b] = first, second
                yield "".join(chars)

    distances = {start: 0}
    queue = [start]
    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        distance = distances[state]
        for nxt in neighbors(state):
            if nxt in distances:
                continue
            new_distance = distance + 1
            if nxt == goal:
                return new_distance
            distances[nxt] = new_distance
            queue.append(nxt)
    return -1

