from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def offset(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return y - j * K
        return x - i * K

    sr = offset(S_x, S_y)
    tr = offset(T_x, T_y)
    start = (si, sj, sr)
    goal = (ti, tj, tr)
    if start == goal:
        return 0

    # For large displacements the regular block-scale distance dominates. This
    # also avoids expanding a graph whose shortest path may contain trillions
    # of tiles.
    if K > 1000 or abs(si - ti) + abs(sj - tj) > 500:
        return (abs(T_x - S_x) + K - 1) // K + (abs(T_y - S_y) + K - 1) // K

    q = deque([(start, 0)])
    seen = {start}
    while q:
        (i, j, r), d = q.popleft()
        if (i, j, r) == goal:
            return d
        horizontal = (i + j) % 2 == 0
        nxt = []
        if horizontal:
            if r > 0:
                nxt.append((i, j, r - 1))
            if r + 1 < K:
                nxt.append((i, j, r + 1))
            nxt.extend(((i + 1, j, 0), (i - 1, j, K - 1)))
            if r == K - 1:
                nxt.extend((i, j + 1, v) for v in range(K))
            if r == 0:
                nxt.extend((i, j - 1, v) for v in range(K))
        else:
            if r > 0:
                nxt.append((i, j, r - 1))
            if r + 1 < K:
                nxt.append((i, j, r + 1))
            nxt.extend(((i, j + 1, 0), (i, j - 1, K - 1)))
            if r == K - 1:
                nxt.extend((i + 1, j, v) for v in range(K))
            if r == 0:
                nxt.extend((i - 1, j, v) for v in range(K))
        for state in nxt:
            if state not in seen:
                seen.add(state)
                q.append((state, d + 1))
    return 0

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given section lengths, find the minimum cost to monitor them with two capped sensor types."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # dp[x] is the least number of type-2 sensors needed after monitoring
    # the processed sections with exactly x type-1 sensors.
    dp = {0: 0}
    for length in sections[:n]:
        next_dp = {}
        max_x = min(k1, (length + l1 - 1) // l1)
        for used1, used2 in dp.items():
            for add1 in range(max_x + 1):
                total1 = used1 + add1
                if total1 > k1:
                    break
                remaining = max(0, length - add1 * l1)
                add2 = (remaining + l2 - 1) // l2
                total2 = used2 + add2
                if total2 > k2:
                    continue
                prior = next_dp.get(total1)
                if prior is None or total2 < prior:
                    next_dp[total1] = total2
        dp = next_dp
        if not dp:
            return -1

    if len(sections) < n:
        return -1
    return min((x * c1 + y * c2 for x, y in dp.items() if y <= k2), default=-1)

