from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to cover each section using capped sensor supplies."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # dp[x] stores the fewest type-2 sensors needed after using exactly x
    # type-1 sensors. For a fixed x, using fewer type-2 sensors dominates.
    dp = {0: 0}
    for length in sections[:n]:
        next_dp = {}
        max_add1 = min(k1, (length + l1 - 1) // l1)
        for used1, used2 in dp.items():
            for add1 in range(max_add1 + 1):
                total1 = used1 + add1
                if total1 > k1:
                    break
                remainder = max(0, length - add1 * l1)
                add2 = (remainder + l2 - 1) // l2
                total2 = used2 + add2
                if total2 <= k2 and total2 < next_dp.get(total1, k2 + 1):
                    next_dp[total1] = total2
        dp = next_dp
        if not dp:
            return -1

    if len(sections) < n:
        return -1
    return min((x * c1 + y * c2 for x, y in dp.items()), default=-1)

def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A positive integer N is a 400 number iff it has exactly two distinct
    prime factors, each with an even exponent. Equivalently, N = m**2 where
    m has exactly two distinct prime factors.
    """
    from bisect import bisect_right
    from math import isqrt

    limit = isqrt(a)
    distinct = [0] * (limit + 1)
    for p in range(2, limit + 1):
        if distinct[p] == 0:
            for multiple in range(p, limit + 1, p):
                distinct[multiple] += 1

    best = 0
    for root in range(2, limit + 1):
        if distinct[root] == 2:
            value = root * root
            if value > best:
                best = value
    return best

