MOD = 998244353


def _advance(mask, label, spoke):
    """Return the subset of current edge directions reachable with this label."""
    out = 0
    for prev in (0, 1):
        if not (mask >> prev) & 1:
            continue
        for cur in (0, 1):
            base = prev + 1 - cur
            if label == base or (spoke and label == base + 1):
                out |= 1 << cur
    return out


def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the specified graph."""
    # Fix the direction of the edge entering vertex 0 (the cycle edge n-1--0).
    # For either fixed value, determinization leaves only four possible subsets
    # of directions for the next cycle edge.
    counts = [0] * 2
    finals = [0] * 2
    for start in (0, 1):
        dp = [0] * 4
        dp[1 << start] = 1
        for spoke_char in s:
            ndp = [0] * 4
            for mask, ways in enumerate(dp):
                if ways == 0:
                    continue
                for label in range(4):
                    nxt = _advance(mask, label, spoke_char == '1')
                    if nxt:
                        ndp[nxt] = (ndp[nxt] + ways) % MOD
            dp = ndp
        counts[start] = sum(dp[mask] for mask in range(4)
                            if (mask >> start) & 1) % MOD
    # A sequence accepted for both starting directions was counted twice.
    # Track both deterministic automata on the same output word.
    dp2 = [0] * 16
    dp2[(1 << 0) * 4 + (1 << 1)] = 1
    for spoke_char in s:
        ndp2 = [0] * 16
        for state, ways in enumerate(dp2):
            if not ways:
                continue
            mask0, mask1 = divmod(state, 4)
            for label in range(4):
                a = _advance(mask0, label, spoke_char == '1')
                b = _advance(mask1, label, spoke_char == '1')
                if a and b:
                    ndp2[a * 4 + b] = (ndp2[a * 4 + b] + ways) % MOD
        dp2 = ndp2
    both = sum(dp2[a * 4 + b] for a in range(4) for b in range(4)
               if (a & 1) and (b & 2)) % MOD
    return (counts[0] + counts[1] - both) % MOD

