from typing import List
from collections import deque
from functools import lru_cache


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, there is a knight at position (kx, ky) and pawns at the given positions.
    Alice and Bob alternate selecting and capturing a remaining pawn, using a shortest knight path.
    Alice maximizes the sum of moves and Bob minimizes it.
    """
    points = [(kx, ky)] + [tuple(p) for p in positions]
    n = len(positions)
    moves = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))

    # Pairwise shortest-path distances on the board.
    dist = [[0] * (n + 1) for _ in range(n + 1)]
    for source, (sx, sy) in enumerate(points):
        board_dist = [[-1] * 50 for _ in range(50)]
        board_dist[sx][sy] = 0
        queue = deque([(sx, sy)])
        while queue:
            x, y = queue.popleft()
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and board_dist[nx][ny] == -1:
                    board_dist[nx][ny] = board_dist[x][y] + 1
                    queue.append((nx, ny))
        for target, (tx, ty) in enumerate(points):
            dist[source][target] = board_dist[tx][ty]

    @lru_cache(None)
    def best(mask: int, current: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        # Alice moves when an even number of pawns have been captured.
        alice_turn = mask.bit_count() % 2 == 0
        value = None
        for i in range(n):
            bit = 1 << i
            if not mask & bit:
                candidate = dist[current][i + 1] + best(mask | bit, i + 1)
                if value is None or (candidate > value if alice_turn else candidate < value):
                    value = candidate
        return value

    return best(0, 0)

