MOD = 998244353

def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts of products of all sequences of lengths 1..n."""
    primes = [2, 3, 5, 7, 11, 13]
    weights = {}
    def block_weight(mask):
        if mask not in weights:
            total = 0
            for x in range(1, m + 1):
                v, term = x, 1
                for i, p in enumerate(primes):
                    if mask >> i & 1:
                        e = 0
                        while v % p == 0:
                            e += 1
                            v //= p
                        term *= e
                total += term
            weights[mask] = total % MOD
        return weights[mask]
    coeff = [0] * 7
    def partitions(mask, blocks):
        if mask == 0:
            value = 1
            for block in blocks:
                value = value * block_weight(block) % MOD
            coeff[len(blocks)] = (coeff[len(blocks)] + value) % MOD
            return
        bit = mask & -mask
        rest = mask ^ bit
        partitions(rest, blocks)
        sub = rest
        while True:
            partitions(rest ^ sub, blocks + [sub | bit])
            if sub == 0:
                break
            sub = (sub - 1) & rest
    partitions(63, [])

    from math import comb
    size = 14
    mat = [[0] * size for _ in range(size)]
    for j in range(7):
        for ell in range(j + 1):
            mat[j][ell] = m * comb(j, ell) % MOD
            mat[7 + j][ell] = m * comb(j, ell) % MOD
        mat[7 + j][7 + j] = 1
    def matmul(a, b):
        out = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if a[i][k]:
                    for j in range(size):
                        if b[k][j]:
                            out[i][j] = (out[i][j] + a[i][k] * b[k][j]) % MOD
        return out
    power, exp = mat, n
    vec = [0] * size
    vec[0] = 1
    while exp:
        if exp & 1:
            vec = [sum(power[i][j] * vec[j] for j in range(size)) % MOD for i in range(size)]
        exp >>= 1
        if exp:
            power = matmul(power, power)
    stirling = [[0] * 7 for _ in range(7)]
    stirling[0][0] = 1
    for b in range(1, 7):
        for j in range(1, b + 1):
            stirling[b][j] = (stirling[b-1][j-1] - (b-1)*stirling[b-1][j]) % MOD
    inv_m = pow(m, MOD - 2, MOD)
    answer = 0
    for b in range(7):
        summed = 0
        for j in range(b + 1):
            sj = vec[7+j] - (1 if j == 0 else 0)
            summed += stirling[b][j] * sj
        answer = (answer + coeff[b] * summed * pow(inv_m, b, MOD)) % MOD
    return answer

