def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in AtCoder's wallpaper."""
    # Each unit square is either uncut, or is split into two equal triangles
    # by one of the diagonal lines. In a split square exactly one triangle is
    # black, so its contribution to twice the black area is one.
    tile = [[0] * 4 for _ in range(4)]
    for i in range(4):
        for j in range(4):
            if (i + j) % 2:
                tile[i][j] = 1
            else:
                # Starting at (0.5, 0.5), crossing x integer lines changes
                # color once per unit of x; the other two line families give
                # the corresponding floor counts below.
                crossings = i + (j + 1) // 2 + (i + j + 1) // 2
                if crossings % 2 == 0:
                    tile[i][j] = 2

    tile_total = sum(map(sum, tile))
    # Prefix sum within one period.
    pref = [[0] * 5 for _ in range(5)]
    for i in range(4):
        for j in range(4):
            pref[i + 1][j + 1] = tile[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j]

    def prefix(x: int, y: int) -> int:
        # Oriented sum over integer cells [0,x) x [0,y); floor division
        # keeps the remainders in the base period even for negative inputs.
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        rows = pref[4][ry]
        cols = pref[rx][4]
        return qx * qy * tile_total + qx * cols + qy * rows + pref[rx][ry]

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in AtCoder's wallpaper."""
    # A unit square with odd lower-left coordinate sum is split in half by a
    # diagonal; exactly one of its two triangles is black.
    tile = [[0] * 4 for _ in range(4)]
    for i in range(4):
        for j in range(4):
            if (i + j) % 2:
                tile[i][j] = 1
            else:
                # Count crossings from the black point (0.5, 0.5) through
                # vertical, horizontal, and diagonal line families.
                crossings = i + j // 2 + (i + j + 1) // 2
                if crossings % 2 == 0:
                    tile[i][j] = 2

    tile_total = sum(map(sum, tile))
    pref = [[0] * 5 for _ in range(5)]
    for i in range(4):
        for j in range(4):
            pref[i + 1][j + 1] = tile[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j]

    def prefix(x: int, y: int) -> int:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        return (qx * qy * tile_total
                + qx * pref[4][ry]
                + qy * pref[rx][4]
                + pref[rx][ry])

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

