from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    values = tuple(grid[r][c] for r in range(3) for c in range(3))
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8),
    )
    line_masks = tuple(sum(1 << i for i in line) for line in lines)
    full_mask = (1 << 9) - 1

    @lru_cache(maxsize=None)
    def play(mask: int, takahashi_mask: int, score_diff: int) -> bool:
        if mask == full_mask:
            return score_diff > 0
        takahashi_turn = mask.bit_count() % 2 == 0
        available = full_mask ^ mask
        while available:
            bit = available & -available
            available -= bit
            index = bit.bit_length() - 1
            new_mask = mask | bit
            if takahashi_turn:
                new_takahashi_mask = takahashi_mask | bit
                new_diff = score_diff + values[index]
                if any((new_takahashi_mask & line) == line for line in line_masks):
                    return True
                if play(new_mask, new_takahashi_mask, new_diff):
                    return True
            else:
                new_takahashi_mask = takahashi_mask
                new_diff = score_diff - values[index]
                aoki_mask = new_mask ^ new_takahashi_mask
                if any((aoki_mask & line) == line for line in line_masks):
                    return False
                if not play(new_mask, new_takahashi_mask, new_diff):
                    return False
        return not takahashi_turn

    return "Takahashi" if play(0, 0, 0) else "Aoki"

MOD = 998244353


def _mat_mul(a, b):
    size = len(a)
    out = [[0] * size for _ in range(size)]
    for i in range(size):
        for k, aik in enumerate(a[i]):
            if aik:
                for j, bkj in enumerate(b[k]):
                    if bkj:
                        out[i][j] = (out[i][j] + aik * bkj) % MOD
    return out


def _mat_pow(a, power):
    size = len(a)
    result = [[int(i == j) for j in range(size)] for i in range(size)]
    while power:
        if power & 1:
            result = _mat_mul(result, a)
        a = _mat_mul(a, a)
        power >>= 1
    return result


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353."""
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    d = len(primes)
    exponents = []
    for value in range(1, m + 1):
        row = []
        for p in primes:
            e = 0
            factor = value
            while factor % p == 0:
                e += 1
                factor //= p
            row.append(e)
        exponents.append(row)

    block_value = [0] * (1 << d)
    for mask in range(1, 1 << d):
        total = 0
        for row in exponents:
            prod = 1
            for i in range(d):
                if mask >> i & 1:
                    prod *= row[i]
            total += prod
        block_value[mask] = total % MOD

    terms = [0] * (d + 1)

    def visit(mask, blocks, product):
        if not mask:
            terms[len(blocks)] = (terms[len(blocks)] + product) % MOD
            return
        bit = mask & -mask
        rest = mask ^ bit
        sub = rest
        while True:
            block = sub | bit
            visit(rest ^ sub, blocks + [block],
                  product * block_value[block] % MOD)
            if sub == 0:
                break
            sub = (sub - 1) & rest

    for mask in range(1 << d):
        visit(mask, [], 1)

    # Track m^k (k)_j and its prefix sum for every j.
    width = d + 1
    size = 2 * width
    trans = [[0] * size for _ in range(size)]
    for j in range(width):
        trans[j][j] = m
        if j:
            trans[j][j - 1] = m * j
        trans[width + j][width + j] = 1
        trans[width + j][j] = trans[j][j]
        if j:
            trans[width + j][j - 1] = trans[j][j - 1]

    powered = _mat_pow(trans, n)
    state = [powered[i][0] for i in range(size)]
    inv_m = pow(m, MOD - 2, MOD)
    answer = 0
    scale = 1
    for r in range(width):
        answer = (answer + terms[r] * state[width + r] * scale) % MOD
        scale = scale * inv_m % MOD
    return answer

