def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    mod = 998244353
    primes = [p for p in range(2, m + 1)
              if all(p % q for q in range(2, int(p ** 0.5) + 1))]
    r = len(primes)
    exps = []
    for x in range(1, m + 1):
        row = []
        for p in primes:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            row.append(e)
        exps.append(row)

    weights = [0] * (1 << r)
    for mask in range(1, 1 << r):
        weights[mask] = sum(
            __import__('math').prod(row[j] for j in range(r) if mask >> j & 1)
            for row in exps
        ) % mod

    coeff = [0] * (r + 1)
    for selected in range(1, 1 << r):
        indices = [j for j in range(r) if selected >> j & 1]
        blocks = []
        def visit(pos):
            if pos == len(indices):
                w = 1
                for b in blocks:
                    w = w * weights[b] % mod
                coeff[len(blocks)] = (coeff[len(blocks)] + w) % mod
                return
            bit = 1 << indices[pos]
            for i in range(len(blocks)):
                blocks[i] |= bit
                visit(pos + 1)
                blocks[i] ^= bit
            blocks.append(bit)
            visit(pos + 1)
            blocks.pop()
        visit(0)

    d = r + 1
    size = 2 * d
    mat = [[0] * size for _ in range(size)]
    for b in range(d):
        mat[b][b] = m
        if b:
            mat[b][b - 1] = b
        for j in range(d):
            mat[d + b][j] = mat[b][j]
        mat[d + b][d + b] = 1

    vec = [0] * size
    vec[0] = 1
    def multiply(a, b):
        out = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if a[i][k]:
                    for j in range(size):
                        if b[k][j]:
                            out[i][j] = (out[i][j] + a[i][k] * b[k][j]) % mod
        return out
    def apply(a, v):
        return [sum(x * y for x, y in zip(row, v)) % mod for row in a]
    power = mat
    e = n
    while e:
        if e & 1:
            vec = apply(power, vec)
        e >>= 1
        if e:
            power = multiply(power, power)

    ans = vec[d]
    for b in range(1, d):
        ans = (ans + coeff[b] * vec[d + b]) % mod
    return ans

